import java.util.Scanner;
class InsufficientFundsException extends Exception { InsufficientFundsException(String message) { super(message); } }
class BankAccount { private double balance; BankAccount(double balance) { this.balance=balance; } void withdraw(double amount) throws InsufficientFundsException { if(amount<0) throw new IllegalArgumentException("Amount cannot be negative."); if(amount>balance) throw new InsufficientFundsException("Insufficient funds."); balance-=amount; System.out.println("Withdrawal successful. Balance = "+balance); } }
public class Q10_Bank_Insufficient_Funds_Exception { public static void main(String[] args) { Scanner sc=new Scanner(System.in); BankAccount account=new BankAccount(1000); try { System.out.print("Enter withdrawal amount: "); account.withdraw(sc.nextDouble()); } catch(InsufficientFundsException e) { System.out.println(e.getMessage()); } catch(IllegalArgumentException e) { System.out.println("Invalid amount: "+e.getMessage()); } finally { sc.close(); } } }
